# ==============================================================================# IOTEC MISSION CONTROL# 003_EVENT_BUS.py# ==============================================================================import jsonimport datetimefrom pathlib import PathROOT = Path(__file__).resolve().parentEVENTS = ROOT / "MISSION_CONTROL" / "events"EVENTS.mkdir(parents=True, exist_ok=True)EVENT_FILE = EVENTS / "event_bus.json"if not EVENT_FILE.exists():    with open(EVENT_FILE, "w", encoding="utf-8") as f:        json.dump([], f)def publish(evento, origem, dados=None):    if dados is None:        dados = {}    with open(EVENT_FILE, encoding="utf-8") as f:        fila = json.load(f)    fila.append({        "id": len(fila) + 1,        "timestamp": datetime.datetime.now().isoformat(),        "evento": evento,        "origem": origem,        "dados": dados    })    with open(EVENT_FILE, "w", encoding="utf-8") as f:        json.dump(fila, f, indent=4, ensure_ascii=False)    print(f"[EVENTO] {evento}")def history():    with open(EVENT_FILE, encoding="utf-8") as f:        return json.load(f)if __name__ == "__main__":    publish(        evento="SYSTEM_START",        origem="003_EVENT_BUS",        dados={            "status": "ONLINE"        }    )    print()    print(history())

